// Guidance never reads an official answer or changes learning/scoring state.
export function mathAnswerGuide(q){return q.answerType==='pair'?'Enter both values as x,y. Keep your working on the paper.':q.type==='clock'?'Enter the time as H:MM, or use the hour and minute controls.':q.answerType==='fraction'?'Enter a fraction as numerator/denominator, for example 1/2.':q.choices?'Choose an answer, then press CHECK ANSWER. Your drawing stays separate.':'Think on the paper, type your final answer, then press CHECK ANSWER.';}
export function spellingModeGuide(mode){return({bee:'Listen → try it on the writing board → type the whole word → Submit.',builder:'Listen → choose letter tiles → arrange them in order → Submit.',missing:'Listen → read the word gaps → type only the missing letters → Submit.',sprint:'Listen → type the word → Submit. Pause whenever you need thinking time.',survival:'Listen carefully → type the word → Submit. Replay and slow speech are available.'})[mode]||'Listen, think, then submit your typed answer.';}
export function learningBadge(){return '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M8 12Q20 7 32 15Q44 7 56 12V51Q44 46 32 54Q20 46 8 51Z" fill="#a8c6b8" stroke="#315a60" stroke-width="3"/><path d="M32 15V54M15 22L25 24M15 30L25 32M39 24L49 22M39 32L49 30" stroke="#315a60" stroke-width="3" fill="none"/><path d="M47 45L53 39L60 46L54 52L43 56Z" fill="#d1b17b" stroke="#315a60" stroke-width="2"/></svg>';}
